target.css:
:root {
  --ink: #183153;
  --paper: #fffdf7;
  --sky: #d9efff;
  --blue: #2878b9;
  --line: #b9d4e5;
}

.claim-card {
  width: 460px;
  overflow: hidden;
  border: 2px solid var(--ink);
  border-radius: 14px;
  background: var(--paper);
}

.claim-card header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 16px;
  background: var(--sky);
  border-bottom: 2px dashed var(--line);
}

.claim-card header section {
  display: flex;
  align-items: baseline;
  gap: 10px;
}

.eyebrow,
.claim-card h2,
.ticket-details p {
  margin: 0;
}

.eyebrow {
  color: var(--blue);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.08em;
}

.claim-card h2 {
  color: var(--ink);
  font-size: 20px;
  line-height: 1;
}

.ticket-number {
  color: var(--ink);
  font-size: 18px;
  font-weight: 800;
}

.ticket-details {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 16px;
}

.ticket-details strong,
.ticket-details span {
  display: block;
}

.ticket-details strong {
  color: var(--ink);
  font-size: 14px;
}

.ticket-details span {
  margin-top: 3px;
  color: var(--blue);
  font-size: 12px;
}

.ticket-details button {
  border: 0;
  border-radius: 8px;
  padding: 8px 10px;
  background: var(--blue);
  color: var(--paper);
  font-size: 12px;
  font-weight: 700;
}

